	@Test
	void plannerAddsLocalOperatorPhysicalCostToInclusiveChildCost() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern input = new StatementPattern(Var.of("subject"), Var.of("predicate"), Var.of("object"));
		Filter filter = new Filter(input, new ValueConstant(values.createLiteral(true)));
		PackedCostModel costs = new PackedCostModel() {

			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return query.isStatementPattern(relationId) ? 10.0d : Double.NaN;
			}

			@Override
			public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.isFilter(relationId)) {
					output.setLocalPhysicalCost(7.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
				}
			}
		};

		PackedPlanningResult result = PackedCascadesPlanner.optimize(filter, OptimizationGoal.root(), costs);

		assertEquals(17.0d, result.totalCost());
	}

	@Test
	void physicalCostCompositionSaturatesAdditiveDimensionsAndMaxesPeakMemory() throws Exception {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setLocalPhysicalCost(1.0d, 1.0d, 1.0d, 1.0d, 1.0d, 1.0d, 1.0d, 1.0d, 10.0d);
		Method addChild = PackedCostEstimate.class.getDeclaredMethod("addChildPhysicalCost", double.class,
				double.class, double.class, double.class, double.class, double.class, double.class, double.class,
				double.class);
		addChild.setAccessible(true);

		addChild.invoke(estimate, 2.0d, 2.0d, 2.0d, 2.0d, 2.0d, 2.0d, 2.0d, 2.0d, 7.0d);

		assertEquals("INCLUSIVE", estimate.costScope().toString());
		assertEquals(3.0d, estimate.sequentialRows());
		assertEquals(24.0d, estimate.workRows());
		assertEquals(10.0d, estimate.peakMemoryRows());

		addChild.invoke(estimate, Double.MAX_VALUE, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 20.0d);

		assertEquals(Double.MAX_VALUE, estimate.sequentialRows());
		assertEquals(Double.MAX_VALUE, estimate.workRows());
		assertEquals(20.0d, estimate.peakMemoryRows());
		assertEquals(24.0d,
				(double) PackedCostSession.class.getMethod("objectiveScore", PackedCostEstimate.class)
						.invoke(PackedCostSession.scalar((query, relationId) -> 1.0d,
								new PackedQueryView(PackedQueryCodec.encode(input()))),
								composedCost()));
	}

